      if (sp_streq(name, "-@") && argc == 0) { buf_puts(b, "sp_rational_neg("); emit_expr(c, recv, b); buf_puts(b, ")"); return 1; }
      if (sp_streq(name, "+@") && argc == 0) { emit_expr(c, recv, b); return 1; }
