        buf_puts(b, "({ "); emit_ctype(c, ht, b); buf_printf(b, " _t%d = ", th);
        emit_expr(c, hs, b);
        buf_printf(b, "; _t%d == NULL ? %d : (sp_%sHash_length(_t%d) %s 0); })",
                   th, eq ? 0 : 1, ty_hash_cname(ht), th, eq ? "==" : "!=");
        return 1;
