      buf_printf(b, "     sp_PolyArray_push(_t%d, _cmd->data[_i]);", tmerged);
      buf_printf(b, "   }");
      buf_printf(b, "   for (sp_int _i = 0; _i < _t%d->len; _i++) sp_PolyArray_push(_t%d, _t%d->data[_i]);", targs, tmerged, targs);
      buf_puts(b, " }");
