      buf_puts(&cv9, "sp_poly_arr_values_at(");
      { Buf rv9; memset(&rv9, 0, sizeof rv9); emit_expr(c, recv, &rv9);
        buf_puts(&cv9, rv9.p ? rv9.p : "sp_box_nil()"); free(rv9.p); }
      buf_printf(&cv9, ", _t%d)", ti9);
